 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next(v for row in grid for v in row if v != 0)
    out = [row[:] for row in grid]

    # Filled wedges are bounded by diagonals that either spread from a
    # single-cell apex or converge to one. Find every complete diagonal wedge.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color:
                continue
            # Wedges opening downward from this apex.
            for d in range(1, min(h-r, c+1, w-c)):
                if grid[r+d][c-d] != color or grid[r+d][c+d] != color:
                    break
                for x in range(c-d+1, c+d):
                    if grid[r+d][x] == 0:
                        out[r+d][x] = 2
            # Wedges closing downward at this apex (the same shape upward).
            for d in range(1, min(r+1, c+1, w-c)):
                if grid[r-d][c-d] != color or grid[r-d][c+d] != color:
                    break
                for x in range(c-d+1, c+d):
                    if grid[r-d][x] == 0:
                        out[r-d][x] = 2
    return out
